import ast

# Parse the code
tree = ast.parse(code)

# Count for loops
for_loops = []
for node in ast.walk(tree):
    if isinstance(node, ast.For):
        for_loops.append(node)

assert len(for_loops) >= 3, f'Should have at least 3 for loops, found {len(for_loops)}'

# Check for enumerate usage
enumerate_used = False
for node in ast.walk(tree):
    if isinstance(node, ast.Call):
        if hasattr(node.func, 'id') and node.func.id == 'enumerate':
            enumerate_used = True
        elif hasattr(node.func, 'attr') and node.func.attr == 'enumerate':
            enumerate_used = True

assert enumerate_used, 'Should use enumerate() function'

# Check for if statement inside loop
if_in_loop = False
for node in ast.walk(tree):
    if isinstance(node, ast.For):
        for child in ast.walk(node):
            if isinstance(child, ast.If):
                if_in_loop = True
                break

assert if_in_loop, 'Should have an if statement inside a for loop'

print('TEST_PASSED: Correct for loop structure')
